@Getter
@AllArgsConstructor
public enum OverlayDisplayMode
{
	ALWAYS("Always"),
	BETWEEN_TASKS("Between tasks"),
	PROXIMITY("Near a slayer master");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

